powerpagecomponent.content:
{
  "source": "{% if request.params['id']%}
{% assign bulkimportId = request.params['id'] %}
{% assign bulkimport =  entities['new_batch'][bulkimportId] %}
{% assign batchType = bulkimport.new_batchestype.value %}
{% endif %}

{% fetchxml invoices %}
<fetch version="1.0" output-format="xml-platform" mapping="logical" distinct="true">
    <entity name="new_invoice">
        <attribute name="new_invoiceid" />
        <attribute name="new_name" />
        <attribute name="new_total" />
        <attribute name="statuscode" />
        <attribute name="new_invoicedate" />
        <attribute name="transactioncurrencyid" />
        <attribute name="new_clientid" />
        <filter type="and">
            <condition attribute="new_batchid" operator="null"/>
            <condition attribute="statuscode" operator="eq" value="100000004"/>
        </filter>
        <link-entity name="account" from="accountid" to="new_clientid" link-type="inner" alias="account">
            <filter type="and">
            <condition attribute="new_bulkimport" operator="eq" value="100000001"/>
            </filter>
        </link-entity>
        <link-entity name="new_invoice_placement" from="new_invoiceid" to="new_invoiceid" visible="false" intersect="true">
            <link-entity name="new_assignment" from="new_assignmentid" to="new_assignmentid" alias="placement">
                <attribute name="new_billfrequency" />
              
            </link-entity>
        </link-entity>
    </entity>
</fetch>
{% endfetchxml%}

{% fetchxml remittances %}
<fetch version="1.0" output-format="xml-platform" mapping="logical" distinct="false">
    <entity name="new_remittance">
        <attribute name="new_remittanceid" />
        <attribute name="new_name" />
        <attribute name="new_supplierid"/>
        <attribute name="new_remittancedate"/>
        <attribute name="new_paytotal"/>
        <attribute name="new_total" />
        <attribute name="transactioncurrencyid" />
        <attribute name="new_batchid"/>
        <attribute name="statuscode" />
        <attribute name="createdon"/>
        <order attribute="new_name" descending="false" />
        <filter type="and">
            <condition attribute="new_batchid" operator="null"/>
            <condition attribute="statuscode" operator="eq" value="100000002"/>
        </filter>
            <link-entity name="account" from="accountid" to="new_supplierid" link-type="inner" alias="aa">
                <filter type="and">
                  <condition attribute="new_bulkimport" operator="eq" value="100000001"/>
                </filter>
            </link-entity>
        
        <link-entity name="new_assignment" from="new_assignmentid" to="new_assignmentid" link-type="inner" alias="placement">
            <attribute name="new_payfrequency" />

        </link-entity>
    </entity>
</fetch>
{% endfetchxml%}


<textarea id="invoiceEvent" style="display: none;">
    [
    {% for invoice in invoices.results.entities %}
        {
            "invoice": {
                "id": "{{ invoice.new_invoiceid | escape }}",
                "title": "{{ invoice.new_name | escape }}"
            },
            "total": "{{ invoice.new_total | plus: 0.0 | round: 2 }}",
            "status": {
                "value": "{{ invoice.statuscode.value | to_string }}",
                "label": "{{ invoice.statuscode.label | escape }}"
            },
            "date": "{{ invoice.new_invoicedate | date: 'dd/MM/yy' }}",
            "currency": "{{ invoice.transactioncurrencyid.name | escape }}",
            "client": {
                "Id": "{{ invoice.new_clientid.id | escape }}",
                "Name": "{{ invoice.new_clientid.name | escape }}"
            },
            "placementDebug": "{{ invoice.placement | inspect }}",
            "billFrequency": "{{invoice['placement.new_billfrequency'].value}}"
        }
        {% if forloop.last == false %},{% endif %}
    {% endfor %}
    ]
</textarea>

<textarea id="remittanceEvent" style="display: none;">
    [
    {% for remittance in remittances.results.entities %}
        {
            "remittance": {
                "id": "{{ remittance.new_remittanceid | escape }}",
                "title": "{{ remittance.new_name | escape }}"
            },
            "supplier": {
                "Id": "{{ remittance.new_supplierid.id | escape }}",
                "Name": "{{ remittance.new_supplierid.name | escape }}"
            },
            "date": "{{ remittance.new_remittancedate | date: 'dd/MM/yy' }}",
            "subTotal": "{{ remittance.new_paytotal | plus: 0.0 | round: 2 }}",
            "total": "{{ remittance.new_total | plus: 0.0 | round: 2 }}",
            "currency": "{{ remittance.transactioncurrencyid.name | escape }}",
            "bulkImports": {
                "Id": "{{ remittance.new_batchid.id | escape }}",
                "Name": "{{ remittance.new_batchid.name | escape }}"
            },
            "status": {
                "value": "{{ remittance.statuscode.value | to_string }}",
                "label": "{{ remittance.statuscode.label | escape }}"
            },
            "placementDebug": "{{ remittance.placement | inspect }}",
            "payFrequency": "{{remittance['placement.new_payfrequency'].value}}",
            "createdOn": "{{ remittance.createdon | date: 'dd/MM/yy' }}"
        }
        {% if forloop.last == false %},{% endif %}
    {% endfor %}
    ]
</textarea>

<section role="dialog" tabindex="-1" style="display: block; padding-left: 0px;">
    <div id="customAddInvoiceModal" class="custom-modal modal-lg modal-dialog">
        <div class="custom-content-modal">
            <div class="custom-modal-header">
                <h2 class="custom-modal-title">Lookup records</h2>
                <button class="closeModalButton modal-close-button" tabindex="0" type="button">
                    <i class="fa-solid fa-xmark"></i>
                    <span>x</span>
                </button>
            </div>
            <div class="custom-modal-body">
                <div class="actions-container">
                    <div class="filter-container">
                        <p>Bill Frequency: </p>
                        <select class="billFrequencyFilter form-control">
                            <option value="all">All</option>
                            <option value="100000000">Weekly</option>
                            <option value="100000001">Monthly</option>
                        </select>
                    </div>
                    <div class="search-container">
                        <input type="text" class="form-control searchBox" placeholder="Search" aria-label="Search invoices">
                        <button class="btn btn-default search-button">
                            <i class="fa fa-search"></i>
                        </button>
                    </div>
                </div>
                <table id="invoiceTable" class="table">
                    <thead>
                        <tr>
                            <th>
                                <input type="checkbox" class="selectAllBulkimports">
                            </th>
                            <th>Name</th>
                            <th>Client</th>
                            <th>Currency</th>
                            <th>Total</th>
                            <th>Status</th>
                            <th>Invoice date</th>
                        </tr>
                    </thead>
                    <tbody>
                        <!-- Rows will be dynamically added here -->
                    </tbody>
                </table>
                <div id="invoiceWarning" class="alert alert-block alert-warning">
                    There are no records to display.
                </div>
                <div class="paginationContainer"></div>
                <div id="selectedBulkimports">
                    <div class="selected-title">
                        <h3>Selected records</h3>
                    </div>
                    <ul class="selectedBulkimportsList"></ul>
                </div>
            </div>
            <div class="custom-modal-footer">
                <button class="addBulkimportsButton btn btn-primary">Add</button>
                <button class="cancelButton btn btn-default">Cancel</button>
            </div>
        </div>
    </div>
</section>

<section role="dialog" tabindex="-1" style="display: block; padding-left: 0px;">
    <div id="customAddRemittanceModal" class="custom-modal modal-lg modal-dialog">
        <div class="custom-content-modal">
            <div class="custom-modal-header">
                <h2 class="custom-modal-title">Lookup records</h2>
                <button class="closeModalButton modal-close-button" tabindex="0" type="button">
                    <i class="fa-solid fa-xmark"></i>
                    <span>x</span>
                </button>
            </div>
            <div class="custom-modal-body">
                <div class="actions-container">
                    <div class="filter-container">
                        <p>Pay Frequency: </p>
                        <select class="billFrequencyFilter form-control">
                            <option value="all">All</option>
                            <option value="100000000">Weekly</option>
                            <option value="100000001">Monthly</option>
                        </select>
                    </div>
                    <div class="search-container">
                        <input type="text" class="form-control searchBox" placeholder="Search" aria-label="Search remittances">
                        <button class="btn btn-default search-button">
                            <i class="fa fa-search"></i>
                        </button>
                    </div>
                </div>
                <table id="remittanceTable" class="table">
                    <thead>
                        <tr>
                            <th>
                                <input type="checkbox" class="selectAllBulkimports">
                            </th>
                            <th>Name</th>
                            <th>Supplier</th>
                            <th>Remittance Date</th>
                            <th>Pay Frequency</th>
                            <th>Sub Total</th>
                            <th>Total</th>
                            <th>Currency</th>
                            <th>Bulk Imports</th>
                            <th>Status Reason</th>
                        </tr>
                    </thead>
                    <tbody>
                        <!-- Rows will be dynamically added here -->
                    </tbody>
                </table>
                <div id="remittanceWarning" class="alert alert-block alert-warning">
                    There are no records to display.
                </div>
                <div class="paginationContainer"></div>
                <div id="selectedBulkimports">
                    <div class="selected-title">
                        <h3>Selected records</h3>
                    </div>
                    <ul class="selectedBulkimportsList"></ul>
                </div>
            </div>
            <div class="custom-modal-footer">
                <button class="addBulkimportsButton btn btn-primary">Add</button>
                <button class="cancelButton btn btn-default">Cancel</button>
            </div>
        </div>
    </div>
</section>

<script type="text/javascript">
    $(document).ready(function () {
        let counter=0;        
        const interval = setInterval(()=>{
            let divButton;
            let addBulkimportButton;
            
            if ( "{{batchType}}" === "100000000" ) {
                divButton = $('#customInvoicesSubgrid .entity-grid.subgrid .view-toolbar .pull-right.toolbar-actions')[0];
                addBulkimportButton = $('#customInvoicesSubgrid .entity-grid.subgrid .view-toolbar.grid-actions .pull-right.toolbar-actions > div:first-child > a');
                console.log("batch type is: {{batchType}}");
            }
            else if ( "{{batchType}}" === "100000001" ) {
                divButton = $('#customRemittancesSubgrid .entity-grid.subgrid .view-toolbar .pull-right.toolbar-actions')[0];
                addBulkimportButton = $('#customRemittancesSubgrid .entity-grid.subgrid .view-toolbar.grid-actions .pull-right.toolbar-actions > div:first-child > a');
                console.log("batch type is: {{batchType}}");
            }
            
            function resetModal(modalId) {  
                let modal = document.getElementById(modalId);
                if (!modal) return;

                console.log(`Resetting modal: ${modalId}`);

                // ✅ Clear the selection array
                selectedBulkimportIds = [];

                // ✅ Clear selected list UI
                let selectedList = modal.querySelector(".selectedBulkimportsList");
                if (selectedList) {
                    selectedList.innerHTML = "";
                }

                let addButton = modal.querySelector(".addBulkimportsButton");
                if (addButton) {
                    addButton.textContent = "Add";
                    addButton.disabled = true;
                }

                let filter = modal.querySelector(".billFrequencyFilter");
                if (filter) {
                    filter.value = "all";
                }

                let searchBox = modal.querySelector(".searchBox");
                if (searchBox) {
                    searchBox.value = "";
                }

                modal.querySelectorAll(".alert-warning").forEach(alert => {
                    alert.style.display = "none";
                });

                modal.querySelectorAll(".paginationContainer").forEach(pagination => {
                    pagination.style.display = "block";
                });

                // ✅ Regenerate the table without checked checkboxes
                window.filterBulkimports();
                        // ✅ Reset select-all checkbox (optional)
                        let selectAllCheckbox = modal.querySelector(".selectAllBulkimports");
                        if (selectAllCheckbox) {
                            selectAllCheckbox.checked = false;
                        }

                        modal.querySelectorAll(".bulkimport-checkbox").forEach(checkbox => {
                                checkbox.checked = false;
                            });
                console.log("Modal reset complete ✅.");
            }

            if(divButton){
                console.log("Div Button Exists:",divButton);
                clearInterval(interval);
 
                addBulkimportButton
                    .on('click', function () {                       
                        event.preventDefault();
                        if ( "{{batchType}}" === "100000000" ) {
                            resetModal("customAddInvoiceModal");
                            $('#customAddInvoiceModal').fadeIn(); 
                            console.log("open custom Add Invoice Modal");
                        }
                        else if ( "{{batchType}}" === "100000001" ) {
                            resetModal("customAddRemittanceModal");
                            $('#customAddRemittanceModal').fadeIn();
                            console.log("open custom Add Remittance Modal");
                        }
                    });
                 
                console.log("Modal appended successfully !");
                
                $('.closeModalButton, .cancelButton').on('click', function () {
                    let modal = this.closest(".custom-modal");
                    if (modal) {
                        // ✅ Clear the selected items BEFORE resetting modal (important!)
                        selectedBulkimportIds = [];

                        resetModal(modal.id);
                        $(modal).fadeOut();
                    }
                });
            }
            else{
                console.log("Button not exists");
                counter++;
                if(counter>10){
                    clearInterval(interval);
                }
            }
        },1000) 
    });

    document.addEventListener("DOMContentLoaded", function () {
        if ( "{{batchType}}" === "100000000" ) {
            var batch_type = "invoice";
            var bulkimportText = document.getElementById("invoiceEvent");

            var selectedBulkimportsList = $('.selectedBulkimportsList')[0];
            var filterSelect = $('.billFrequencyFilter')[0];
        }
        else if ( "{{batchType}}" === "100000001" ) {
            var batch_type = "remittance";
            var bulkimportText = document.getElementById("remittanceEvent");

            var selectedBulkimportsList = $('.selectedBulkimportsList')[1];
            var filterSelect = $('.billFrequencyFilter')[1];
        }

        console.log("Bulkimport Text: ",bulkimportText);

        window.bulkimportData = null;
        try{
            window.bulkimportData = JSON.parse(bulkimportText.value);
            console.log(`${batch_type} Data: `,window.bulkimportData);
        } catch (error) {
            console.error(`Failed to parse ${batch_type} data :`, error);
        }

        var invoiceTableBody = document.querySelector("#invoiceTable tbody");
        var remittanceTableBody = document.querySelector("#remittanceTable tbody");

        var selectedBulkimportIds = [];

        function searchTable() {
            if ("{{batchType}}" === "100000000") {
                var searchTerm = $($('.searchBox')[0]).val().toLowerCase();
                var bulkimportTable = "#invoiceTable";
                var warningMessage = "#invoiceWarning";
                var tableBody = $("#invoiceTable tbody");
            } else if ("{{batchType}}" === "100000001") {
                var searchTerm = $($('.searchBox')[1]).val().toLowerCase();
                var bulkimportTable = "#remittanceTable";
                var warningMessage = "#remittanceWarning";
                var tableBody = $("#remittanceTable tbody");
            }

            window.filterBulkimports();
            var filteredRows = [];

            $(`${bulkimportTable} tbody tr`).each(function() {
                var rowText = $(this).text().toLowerCase();
                if (rowText.includes(searchTerm)) {
                    filteredRows.push($(this).clone());
                }
            });

            tableBody.empty();

            if (filteredRows.length > 0) {
                filteredRows.forEach(row => tableBody.append(row));
                $(warningMessage).hide();
                paginateTable(tableBody[0], 10);
                $('.paginationContainer').show();
            }
            else {
                $(warningMessage).show();
                $('.paginationContainer').hide();
            }
            attachCheckboxListeners();
        }
        $('.searchBox').on('keydown', function(e) {
            if (e.key === "Enter") {
                e.preventDefault();   // prevent refresh after press enter
                searchTable();        // execute the search
            }
        });
        $('.search-button').on('click', function(event) {
            event.preventDefault();
            searchTable();
        });

        function updateWarningMessage(tableBody, warningMessage) {
            if ($(tableBody).children().length === 0) {
                $(warningMessage).show();
                $('.paginationContainer').hide();
            } else {
                $(warningMessage).hide();
                $('.paginationContainer').show();
            }
        }

        window.filterBulkimports = function () {
            $('#invoiceWarning').hide();
            $('#remittanceWarning').hide();

            $('.paginationContainer').show();

            var selectedValue = filterSelect.value;

            invoiceTableBody.innerHTML = "";
            remittanceTableBody.innerHTML = "";
            // selectedBulkimportsList.innerHTML = "";

            function isInSubgridData(id) {
                if (!Array.isArray(window.subgridData)) {
                    console.warn("subgridData is not initialized or not an array. Initializing...");
                    window.subgridData = []; 
                }

                return window.subgridData.some(item =>
                    (item.invoice && item.invoice.id === id) ||
                    (item.remittance && item.remittance.id === id)
                );
            }

            if ( "{{batchType}}" === "100000000" ) {
                window.bulkimportData.forEach(function (invoice) {
                    if ((selectedValue === "all" || invoice.billFrequency === selectedValue) && !isInSubgridData(invoice.invoice.id)) {

                        var row = document.createElement("tr");
                        row.innerHTML = `
                            <td><input type="checkbox" name="bulkimport" class="bulkimport-checkbox" data-id="${invoice.invoice.id}" data-title="${invoice.invoice.title}"></td>
                            <td>${invoice.invoice.title}</td>
                            <td>${invoice.client.Name}</td>
                            <td>${invoice.currency}</td>
                            <td>${invoice.total}</td>
                            <td>${invoice.status.label}</td>
                            <td>${invoice.date}</td>
                        `;
                        // invoiceTableBody.appendChild(row);
                        if (selectedBulkimportIds.includes(invoice.invoice.id)) {
                            row.querySelector('.bulkimport-checkbox').checked = true;
                        }
                        invoiceTableBody.appendChild(row);
                    }
                });
                updateWarningMessage("#invoiceTable tbody", "#invoiceWarning");
                paginateTable(invoiceTableBody, 10);
            }
            else if ( "{{batchType}}" === "100000001" ) {
                window.bulkimportData.forEach(function (remittance) {
                    if ((selectedValue === "all" || remittance.payFrequency === selectedValue) && !isInSubgridData(remittance.remittance.id)) {

                        var row = document.createElement("tr");
                        var payFrequencyText = remittance.payFrequency === "100000000" ? "Weekly" : remittance.payFrequency === "100000001" ? "Monthly" : remittance.payFrequency;

                        row.innerHTML = `
                            <td><input type="checkbox" name="bulkimport" class="bulkimport-checkbox" data-id="${remittance.remittance.id}" data-title="${remittance.remittance.title}" data-createdon="${remittance.createdOn}"></td>
                            <td>${remittance.remittance.title}</td>
                            <td>${remittance.supplier.Name}</td>
                            <td>${remittance.date}</td>
                            <td>${payFrequencyText}</td>
                            <td>${remittance.subTotal}</td>
                            <td>${remittance.total}</td>
                            <td>${remittance.currency}</td>
                            <td>${remittance.bulkImports.Name}</td>
                            <td>${remittance.status.label}</td>
                        `;
                        if (selectedBulkimportIds.includes(remittance.remittance.id)) {
                            row.querySelector('.bulkimport-checkbox').checked = true;
                        }
                        remittanceTableBody.appendChild(row);
                        // remittanceTableBody.appendChild(row);
                    }
                });
                updateWarningMessage("#remittanceTable tbody", "#remittanceWarning");
                paginateTable(remittanceTableBody, 10);
            }
            attachCheckboxListeners();        
        };

        $(document).on('DOMNodeInserted', '#invoiceTable tbody, #remittanceTable tbody', function() {
            updateWarningMessage("#invoiceTable tbody", "#invoiceWarning");
            updateWarningMessage("#remittanceTable tbody", "#remittanceWarning");
        });

        function paginateTable(tableBody, rowsPerPage) {
            var rows = tableBody.querySelectorAll('tr');
            var totalPages = Math.ceil(rows.length / rowsPerPage);
            var currentPage = 1;
            var maxVisiblePages = 10;

            function showPage(page) {
                var start = (page - 1) * rowsPerPage;
                var end = start + rowsPerPage;
                rows.forEach((row, index) => {
                    row.style.display = (index >= start && index < end) ? '' : 'none';
                });
            }

            function createPaginationControls() {
                if ( "{{batchType}}" === "100000000" ) {
                    var paginationContainer = $('.paginationContainer')[0];
                } else if ( "{{batchType}}" === "100000001" ) {
                    var paginationContainer = $('.paginationContainer')[1];
                }

                if (!paginationContainer) {
                    console.error("Pagination container not found!");
                    return;
                }
                paginationContainer.innerHTML = "";

                var paginationWrapper = document.createElement('div');
                paginationWrapper.className = 'pagination-wrapper';

                var paginationControls = document.createElement('ul');
                paginationControls.className = 'pagination-controls';

                var prevButton = document.createElement('li');
                prevButton.innerHTML = '<';
                prevButton.classList.add('pagination-prev');
                if (currentPage === 1) {
                    prevButton.classList.add('disabled');
                }
                prevButton.addEventListener('click', function (event) {
                    event.preventDefault();
                    if (currentPage > 1) {
                        currentPage--;
                        showPage(currentPage);
                        createPaginationControls();
                    }
                });
                paginationControls.appendChild(prevButton);
            
                // Dynamic Page Numbering
                if (totalPages <= maxVisiblePages) {
                    for (let i = 1; i <= totalPages; i++) {
                        paginationControls.appendChild(createPageButton(i));
                    }
                } else {
                    paginationControls.appendChild(createPageButton(1));

                    if (currentPage > 4) {
                        paginationControls.appendChild(createEllipsis());
                    }

                    let start = Math.max(2, currentPage - 2);
                    let end = Math.min(totalPages - 1, currentPage + 2);

                    for (let i = start; i <= end; i++) {
                        paginationControls.appendChild(createPageButton(i));
                    }

                    if (currentPage < totalPages - 3) {
                        paginationControls.appendChild(createEllipsis());
                    }

                    paginationControls.appendChild(createPageButton(totalPages));
                }

                var nextButton = document.createElement('li');
                nextButton.innerHTML = '>';
                nextButton.classList.add('pagination-next');
                if (currentPage === totalPages) {
                    nextButton.classList.add('disabled');
                }
                nextButton.addEventListener('click', function (event) {
                    event.preventDefault();
                    if (currentPage < totalPages) {
                        currentPage++;
                        showPage(currentPage);
                        createPaginationControls();
                    }
                });
                paginationControls.appendChild(nextButton);

                paginationWrapper.appendChild(paginationControls);
                paginationContainer.appendChild(paginationWrapper);
            }

            function createPageButton(pageNumber) {
                let pageButton = document.createElement('li');
                pageButton.textContent = pageNumber;
                pageButton.classList.add('pagination-page');
                if (pageNumber === currentPage) {
                    pageButton.classList.add('active');
                }
                pageButton.addEventListener('click', function (event) {
                    event.preventDefault();
                    currentPage = pageNumber;
                    showPage(currentPage);
                    createPaginationControls();
                });
                return pageButton;
            }

            function createEllipsis() {
                let ellipsis = document.createElement('li');
                ellipsis.textContent = '...';
                ellipsis.classList.add('disabled');
                return ellipsis;
            }

            showPage(currentPage);
            createPaginationControls();
        }

        function attachCheckboxListeners() {
            var checkboxes = document.querySelectorAll(".bulkimport-checkbox");
            checkboxes.forEach(function (checkbox) {
                checkbox.addEventListener("change", function () {
                    updateSelectedBulkimports();
                    updateSelectAllCheckbox();
                });
            });
        }

        document.querySelectorAll('.selectAllBulkimports').forEach(function(element) {
            element.addEventListener('change', function(event) {
                var checkboxes = document.querySelectorAll('.bulkimport-checkbox');
                checkboxes.forEach(function(checkbox) {
                    checkbox.checked = event.target.checked;
                });
                updateSelectedBulkimports();
                updateSelectAllCheckbox();
            });
        });

        function updateSelectedBulkimports() {
            const batchType = "{{batchType}}";
            selectedBulkimportsList.innerHTML = "";

            // Refresh selectedBulkimportIds from checkboxes in current view
            document.querySelectorAll(".bulkimport-checkbox").forEach(function (checkbox) {
                const id = checkbox.dataset.id;

                if (checkbox.checked) {
                    if (!selectedBulkimportIds.includes(id)) {
                        selectedBulkimportIds.push(id);
                    }
                } else {
                    // If unchecked, remove from selected list
                    selectedBulkimportIds = selectedBulkimportIds.filter(x => x !== id);
                }
            });

            // Now render all selected items using `bulkimportData`
            selectedBulkimportIds.forEach(function (id) {
                let item;

                if (batchType === "100000000") {
                    item = window.bulkimportData.find(d => d.invoice.id === id);
                } else if (batchType === "100000001") {
                    item = window.bulkimportData.find(d => d.remittance.id === id);
                }

                if (!item) return;

                const title = batchType === "100000000" ? item.invoice.title : item.remittance.title;

                const li = document.createElement("li");
                li.textContent = title;

                const deleteButton = document.createElement("button");
                deleteButton.textContent = "x";
                deleteButton.className = "delete-button";
                deleteButton.addEventListener("click", function () {
                    li.remove();
                    selectedBulkimportIds = selectedBulkimportIds.filter(x => x !== id);

                    // Uncheck if checkbox exists
                    const checkbox = document.querySelector(`.bulkimport-checkbox[data-id="${id}"]`);
                    if (checkbox) checkbox.checked = false;

                    updateSelectedBulkimports();
                });

                li.appendChild(deleteButton);
                selectedBulkimportsList.appendChild(li);
            });

            $('.addBulkimportsButton').prop('disabled', selectedBulkimportIds.length === 0);
            updateSelectAllCheckbox();
            console.log("Updated selected IDs:", selectedBulkimportIds);
        }

        function updateSelectAllCheckbox() {
            var checkboxes = document.querySelectorAll(".bulkimport-checkbox");
            var selectAllCheckbox = document.querySelector(".selectAllBulkimports");

            if (checkboxes.length === 0) {
                selectAllCheckbox.checked = false;
                return;
            }

            var allChecked = true;
            checkboxes.forEach(function (checkbox) {
                if (!checkbox.checked) {
                    allChecked = false;
                }
            });

            selectAllCheckbox.checked = allChecked;
        }

        filterSelect.addEventListener("change", window.filterBulkimports);

        if ($('#customAddInvoiceModal').length || $('#customAddRemittanceModal').length) {
            window.filterBulkimports();
        }

        $('.addBulkimportsButton').prop('disabled', true);

        $('#invoiceTable tbody, #remittanceTable tbody').on('mouseenter', 'tr', function () {
            if (!$(this).find('.bulkimport-checkbox').prop('checked')) {
                $(this).css('background-color', '#dcffff');
            }
        }).on('mouseleave', 'tr', function () {
            if (!$(this).find('.bulkimport-checkbox').prop('checked')) {
                $(this).css('background-color', '');
            }
        });

        $('#invoiceTable tbody, #remittanceTable tbody').on('change', '.bulkimport-checkbox', function () {
            let row = $(this).closest('tr');
            if ($(this).prop('checked')) {
                row.css('background-color', '#f3f2f1');
            } else {
                row.css('background-color', row.is(':hover') ? '#dcffff' : '');
            }
        });

        document.querySelectorAll('.addBulkimportsButton').forEach(function(button) {
            button.addEventListener('click', function(event) {
                event.preventDefault();
                if ($('input[type=checkbox][name=bulkimport]:checked').length > 0) {
                    console.log(`The array of selected ${batch_type}s Ids: `, selectedBulkimportIds);
                }
                window.populateBulkImport(selectedBulkimportIds);
            });
        });

        document.querySelectorAll('.cancelButton').forEach(function(button) {
            button.addEventListener('click', function(event) {
                event.preventDefault();
                document.getElementById('customAddInvoiceModal').style.display = 'none';
                document.getElementById('customAddRemittanceModal').style.display = 'none';
            });
        });

    });
</script>
"
}
